import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 16

__device__ int get_output_size(int input_size, int kernel_size, int padding, int stride, int dilation) {
    return (input_size + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
}

__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size, int in_channels, int in_height, int in_width,
    int out_channels, int kernel_size, int stride, int padding, int dilation, int groups,
    int out_height, int out_width
) {
    const int c_out = blockIdx.y * blockDim.y + threadIdx.y;
    const int n = blockIdx.z;

    const int h_out = blockIdx.x * blockDim.x + threadIdx.x;
    const int w_out = blockIdx.x * blockDim.x + threadIdx.x;

    if (n >= batch_size || c_out >= out_channels || h_out >= out_height || w_out >= out_width) return;

    const int group_size = out_channels / groups;
    const int group = c_out / group_size;
    const int c_in_start = group * (in_channels / groups);
    const int c_in_end = c_in_start + (in_channels / groups);

    float sum = 0.0f;

    for (int c_in = c_in_start; c_in < c_in_end; ++c_in) {
        for (int i = 0; i < kernel_size; ++i) {
            for (int j = 0; j < kernel_size; ++j) {
                const int h_in = h_out * stride - padding + i * dilation;
                const int w_in = w_out * stride - padding + j * dilation;

                if (h_in >= 0 && h_in < in_height && w_in >= 0 && w_in < in_width) {
                    const int input_idx = n * in_channels * in_height * in_width + 
                                       c_in * in_height * in_width + 
                                       h_in * in_width + w_in;
                    const int weight_idx = c_out * (in_channels/groups) * kernel_size * kernel_size + 
                                       (c_in - c_in_start) * kernel_size * kernel_size + 
                                       i * kernel_size + j;
                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    if (bias) sum += bias[c_out];

    const int output_idx = n * out_channels * out_height * out_width + 
                         c_out * out_height * out_width + 
                         h_out * out_width + w_out;
    output[output_idx] = sum;
}

torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    int groups
) {
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int in_height = input.size(2);
    const int in_width = input.size(3);
    const int out_channels = weight.size(0);

    const int out_height = get_output_size(in_height, kernel_size, padding, stride, dilation);
    const int out_width = get_output_size(in_width, kernel_size, padding, stride, dilation);

    auto output = torch::zeros({batch_size, out_channels, out_height, out_width}, input.options());

    const dim3 block(BLOCK_SIZE, BLOCK_SIZE);
    const dim3 grid(
        (out_height * out_width + BLOCK_SIZE - 1) / BLOCK_SIZE,
        (out_channels + BLOCK_SIZE - 1) / BLOCK_SIZE,
        batch_size
    );

    conv2d_forward_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, in_height, in_width,
        out_channels, kernel_size, stride, padding, dilation, groups,
        out_height, out_width
    );

    return output;
}
"""

conv2d_cpp_source = "torch::Tensor conv2d_forward_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int kernel_size, int stride, int padding, int dilation, int groups);"

conv2d_custom = load_inline(
    name="conv2d_custom",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_cuda_source,
    functions=["conv2d_forward_cuda"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        self.weight = nn.Parameter(torch.Tensor(
            out_channels,
            in_channels // groups,
            kernel_size,
            kernel_size
        ))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)

        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        if bias:
            nn.init.zeros_(self.bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv2d_custom.conv2d_forward_cuda(
            x,
            self.weight,
            self.bias if self.bias is not None else torch.Tensor(),
            self.kernel_size,
            self.stride,
            self.padding,
            self.dilation,
            self.groups
        )
